// ---- QR code (byte mode, correcao L, versoes 1-10). Sem bibliotecas. ----
var HZQR = (function () {
  var EXP = [], LOG = [], i, x = 1;
  for (i = 0; i < 255; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 256) x ^= 285; }
  for (i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
  function mul(a, b) { return a && b ? EXP[LOG[a] + LOG[b]] : 0; }
  function rs(data, n) {                       // codigos de correcao de erro Reed-Solomon
    var g = [1], j, k;
    for (j = 0; j < n; j++) {
      var ng = [];
      for (k = 0; k <= g.length; k++) ng[k] = (g[k] || 0) ^ mul(g[k - 1] || 0, EXP[j]);
      g = ng;
    }
    var r = [];
    for (j = 0; j < n; j++) r[j] = 0;
    for (j = 0; j < data.length; j++) {
      var f = data[j] ^ r[0];
      r.shift(); r.push(0);
      for (k = 0; k < n; k++) r[k] ^= mul(g[k + 1], f);
    }
    return r;
  }
  // por versao: [ec por bloco, blocos grupo1, dados grupo1, blocos grupo2, dados grupo2]
  var VER = [null, [7,1,19,0,0],[10,1,34,0,0],[15,1,55,0,0],[20,1,80,0,0],[26,1,108,0,0],[18,2,68,0,0],[20,2,78,0,0],[24,2,97,0,0],[30,2,116,0,0],[18,2,68,2,69]];
  var ALIGN = [null, [], [6,18],[6,22],[6,26],[6,30],[6,34],[6,22,38],[6,24,42],[6,26,46],[6,28,50]];
  function bch(v, poly, bits) {
    var d = v << bits, p = poly, ph = 0, t = poly;
    while (t >> (ph + 1)) ph++;
    for (var s = 31; s >= ph; s--) if ((d >> s) & 1) d ^= poly << (s - ph);
    return (v << bits) | d;
  }
  function make(text) {
    var bytes = [];
    var u = unescape(encodeURIComponent(text));
    for (i = 0; i < u.length; i++) bytes.push(u.charCodeAt(i));
    var ver = 0, tot;
    for (var v = 1; v <= 10; v++) {
      var V = VER[v]; tot = V[1] * V[2] + V[3] * V[4];
      if (bytes.length + (v < 10 ? 2 : 3) <= tot) { ver = v; break; }
    }
    if (!ver) return null;
    var V = VER[ver]; tot = V[1] * V[2] + V[3] * V[4];
    var bits = [];
    function put(val, n) { for (var b = n - 1; b >= 0; b--) bits.push((val >> b) & 1); }
    put(4, 4); put(bytes.length, ver < 10 ? 8 : 16);
    for (i = 0; i < bytes.length; i++) put(bytes[i], 8);
    for (i = 0; i < 4 && bits.length < tot * 8; i++) bits.push(0);
    while (bits.length % 8) bits.push(0);
    var cw = [];
    for (i = 0; i < bits.length; i += 8) { var by = 0; for (var q = 0; q < 8; q++) by = by * 2 + bits[i + q]; cw.push(by); }
    for (i = 0; cw.length < tot; i++) cw.push(i % 2 ? 17 : 236);
    var blocks = [], pos = 0, bi;
    for (bi = 0; bi < V[1] + V[3]; bi++) {
      var len = bi < V[1] ? V[2] : V[4];
      var d = cw.slice(pos, pos + len); pos += len;
      blocks.push({ d: d, e: rs(d, V[0]) });
    }
    var fin = [], maxd = Math.max(V[2], V[4]);
    for (i = 0; i < maxd; i++) blocks.forEach(function (b) { if (i < b.d.length) fin.push(b.d[i]); });
    for (i = 0; i < V[0]; i++) blocks.forEach(function (b) { fin.push(b.e[i]); });

    var N = ver * 4 + 17, M = [], R = [];       // M = modulos, R = reservado (funcao)
    for (i = 0; i < N; i++) { M.push([]); R.push([]); }
    function set(r, c, val) { if (r >= 0 && c >= 0 && r < N && c < N) { M[r][c] = val ? 1 : 0; R[r][c] = 1; } }
    function finder(r, c) {
      for (var a = -1; a <= 7; a++) for (var b = -1; b <= 7; b++) {
        var on = a >= 0 && a <= 6 && b >= 0 && b <= 6 && (a === 0 || a === 6 || b === 0 || b === 6 || (a >= 2 && a <= 4 && b >= 2 && b <= 4));
        set(r + a, c + b, on);
      }
    }
    finder(0, 0); finder(0, N - 7); finder(N - 7, 0);
    for (i = 8; i < N - 8; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }
    var al = ALIGN[ver];
    al.forEach(function (r) { al.forEach(function (c) {
      if ((r === 6 && c === 6) || (r === 6 && c === al[al.length - 1]) || (c === 6 && r === al[al.length - 1])) return;
      for (var a = -2; a <= 2; a++) for (var b = -2; b <= 2; b++) set(r + a, c + b, Math.max(Math.abs(a), Math.abs(b)) !== 1);
    }); });
    set(N - 8, 8, 1);                            // modulo escuro fixo
    for (i = 0; i < 9; i++) { if (!R[8][i]) set(8, i, 0); if (!R[i][8]) set(i, 8, 0); }
    for (i = 0; i < 8; i++) { if (!R[8][N - 1 - i]) set(8, N - 1 - i, 0); if (!R[N - 1 - i][8]) set(N - 1 - i, 8, 0); }
    if (ver >= 7) for (i = 0; i < 6; i++) for (var j2 = 0; j2 < 3; j2++) { set(i, N - 11 + j2, 0); set(N - 11 + j2, i, 0); }
    // dados em zigue-zague
    var all = [];
    fin.forEach(function (b) { for (var s = 7; s >= 0; s--) all.push((b >> s) & 1); });
    var rem = ver >= 2 && ver <= 6 ? 7 : 0; while (rem--) all.push(0);
    var bit = 0, up = true, col;
    var DATA = []; for (i = 0; i < N; i++) DATA.push([]);
    for (col = N - 1; col > 0; col -= 2) {
      if (col === 6) col--;
      for (var t = 0; t < N; t++) {
        var rr = up ? N - 1 - t : t;
        for (var cc = 0; cc < 2; cc++) {
          var c2 = col - cc;
          if (!R[rr][c2]) { DATA[rr][c2] = bit < all.length ? all[bit] : 0; bit++; }
        }
      }
      up = !up;
    }
    var MASK = [
      function (r, c) { return (r + c) % 2 === 0; }, function (r) { return r % 2 === 0; },
      function (r, c) { return c % 3 === 0; }, function (r, c) { return (r + c) % 3 === 0; },
      function (r, c) { return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0; },
      function (r, c) { return (r * c) % 2 + (r * c) % 3 === 0; },
      function (r, c) { return ((r * c) % 2 + (r * c) % 3) % 2 === 0; },
      function (r, c) { return ((r + c) % 2 + (r * c) % 3) % 2 === 0; }
    ];
    function build(mk) {
      var G = [], r, c;
      for (r = 0; r < N; r++) { G.push([]); for (c = 0; c < N; c++) G[r][c] = R[r][c] ? M[r][c] : (DATA[r][c] ^ (MASK[mk](r, c) ? 1 : 0)); }
      var f = bch((1 << 3) | mk, 0x537, 10) ^ 0x5412;       // correcao L = 01
      for (i = 0; i < 15; i++) {
        var b = (f >> i) & 1;
        if (i < 6) G[i][8] = b; else if (i < 8) G[i + 1][8] = b; else G[N - 15 + i][8] = b;
        if (i < 8) G[8][N - 1 - i] = b; else if (i < 9) G[8][15 - i] = b; else G[8][14 - i] = b;
      }
      G[N - 8][8] = 1;
      if (ver >= 7) {
        var vi = bch(ver, 0x1f25, 12);
        for (i = 0; i < 18; i++) { var vb = (vi >> i) & 1; G[Math.floor(i / 3)][N - 11 + (i % 3)] = vb; G[N - 11 + (i % 3)][Math.floor(i / 3)] = vb; }
      }
      return G;
    }
    function penalty(G) {
      var p = 0, r, c, run, dark = 0;
      for (var o = 0; o < 2; o++) for (r = 0; r < N; r++) {
        run = 1;
        for (c = 1; c < N; c++) {
          var a = o ? G[c][r] : G[r][c], b = o ? G[c - 1][r] : G[r][c - 1];
          if (a === b) { run++; if (run === 5) p += 3; else if (run > 5) p++; } else run = 1;
        }
      }
      for (r = 0; r < N - 1; r++) for (c = 0; c < N - 1; c++) if (G[r][c] === G[r][c + 1] && G[r][c] === G[r + 1][c] && G[r][c] === G[r + 1][c + 1]) p += 3;
      var pat = [1,0,1,1,1,0,1,0,0,0,0], pat2 = pat.slice().reverse();
      for (var o2 = 0; o2 < 2; o2++) for (r = 0; r < N; r++) for (c = 0; c <= N - 11; c++) {
        var m1 = true, m2 = true;
        for (var k = 0; k < 11; k++) { var vv = o2 ? G[c + k][r] : G[r][c + k]; if (vv !== pat[k]) m1 = false; if (vv !== pat2[k]) m2 = false; }
        if (m1) p += 40; if (m2) p += 40;
      }
      for (r = 0; r < N; r++) for (c = 0; c < N; c++) dark += G[r][c];
      p += Math.floor(Math.abs(dark * 100 / (N * N) - 50) / 5) * 10;
      return p;
    }
    var best = null, bp = 1e9;
    for (var mk = 0; mk < 8; mk++) { var g = build(mk), pp = penalty(g); if (pp < bp) { bp = pp; best = g; } }
    return best;
  }
  // SVG pronto: modulos pretos sobre fundo branco com margem de 3 modulos
  function svg(text) {
    var G = make(text);
    if (!G) return "";
    var N = G.length, q = 3, d = "", r, c;
    for (r = 0; r < N; r++) for (c = 0; c < N; c++) if (G[r][c]) d += "M" + (c + q) + " " + (r + q) + "h1v1h-1z";
    var s = N + q * 2;
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + s + " " + s + '" shape-rendering="crispEdges"><rect width="' + s + '" height="' + s + '" fill="#fff"/><path d="' + d + '" fill="#000"/></svg>';
  }
  return { make: make, svg: svg };
})();

