// ---------- guardar preferencias ----------
function store(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
function recall(k, d) {
  try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; }
}

function validStyle(k) {
  for (var i = 0; i < STYLES.length; i++) if (STYLES[i].key === k) return true;
  return false;
}
function applyStyle(k) { document.documentElement.setAttribute("data-style", k); }
function applyTheme() { document.documentElement.setAttribute("data-theme", theme); }
function toggleTheme() {
  theme = theme === "dark" ? "default" : "dark";
  store("hz_theme", theme);
  applyTheme(); refreshRows();
}

// ============================================================
// NAVEGACAO - uma pilha de telas e UM unico tratador de teclas.
//   push("settings") abre por cima; pop() volta para a anterior.
//   Voltar sempre sobe um nivel: picker/org -> (config) -> home -> sai.
// ============================================================
function push(s) { stack.push(screen); screen = s; renderScreens(); }
function pop() { screen = stack.length ? stack.pop() : "home"; renderScreens(); }
function renderScreens() {
  var all = stack.concat([screen]);
  $("vmenu").classList.toggle("open", screen === "picker");
  $("omenu").classList.toggle("open", screen === "org");
  $("reader").classList.toggle("open", screen === "reader");
  $("prompt").classList.toggle("open", screen === "prompt");
  document.body.classList.toggle("tab-settings", all.indexOf("settings") >= 0);
  refreshFocus();
}
function canPoint() { return introDone && screen === "home"; }

