function closeAll() {
  if (pk) { var p = pk; pk = null; p.preview(p.cur()); }
  if (orgOpen) { orgOpen = false; oMode = "nav"; if (oDirty) APPS = oBackup.slice(); oDirty = false; }
  stack = []; screen = "home";
  renderScreens(); refreshFocus();
}

// ---------- barra do topo: [abas (Cyber)] + [Organizar, Lifestyle, Visual, Config.] ----------
var TOOLS = [
  { id: "obtn", act: function () { openOrg(); } },
  { id: "lbtn", act: function () { openLife(); } },
  { id: "vbtn", act: function () { openVisual(); } },
  { id: "sbtn", act: function () { openSettings(); } }
];
var TAB_NAME = { home: "Início", news: "Notícias", inputs: "Entradas" };
function tabList() { return showNews ? ["home", "news", "inputs"] : ["home", "inputs"]; }

function hdrItems() {
  var l = [];
  if (life === "cyber") tabList().forEach(function (t) { l.push({ el: $("tab-" + t), tab: t }); });
  TOOLS.forEach(function (t) { l.push({ el: $(t.id), act: t.act }); });
  return l;
}
function hdrFind(el) {
  var L = hdrItems();
  for (var i = 0; i < L.length; i++) if (L[i].el === el) return i;
  return -1;
}
function hdrAt(i) {
  var L = hdrItems();
  if (i < 0 || i >= L.length) return;
  hdrIndex = i;
  if (L[i].tab) setTab(L[i].tab);          // abas trocam ao receber o foco
  else refreshFocus();
}
function hdrOK() {
  var it = hdrItems()[hdrIndex];
  if (!it) return;
  if (it.tab) { zone = "content"; refreshFocus(); }
  else if (it.act) it.act();
}
function wireHdr(el) {
  el.addEventListener("mouseenter", function () {
    if (!canPoint()) return;
    var i = hdrFind(el);
    if (i >= 0 && !(zone === "header" && hdrIndex === i)) { zone = "header"; hdrAt(i); }
  });
  el.addEventListener("click", function () {
    if (!canPoint()) return;
    var i = hdrFind(el);
    if (i >= 0) { zone = "header"; hdrAt(i); hdrOK(); }
  });
}
function buildTabs() {
  var box = $("tabs");
  box.innerHTML = "";
  tabList().forEach(function (t) {
    var d = document.createElement("div");
    d.className = "tab"; d.id = "tab-" + t; d.textContent = TAB_NAME[t];
    box.appendChild(d);
    wireHdr(d);
  });
}
function setTab(t) {
  cyTab = t; cyRow = 0;
  $("cyber").setAttribute("data-tab", t);
  refreshFocus();
}
function toHeader() {
  zone = "header";
  hdrIndex = life === "cyber" ? Math.max(0, tabList().indexOf(cyTab)) : 0;
  refreshFocus();
}

// ---------- apps (grade no Basic, fileira no Cyber) ----------
function gridEl() { return life === "cyber" ? $("crow") : $("grid"); }

function buildCells() {
  $("grid").innerHTML = ""; $("crow").innerHTML = "";
  var grid = gridEl();
  cells = []; focusEl = null; applied = {};
  $("grid").className = "grid" + (APPS.length > 10 ? " dense" : "");
  var frag = document.createDocumentFragment();
  APPS.forEach(function (app, i) {
    var cell = document.createElement("div");
    cell.className = "app";
    cell.style.setProperty("--n", i);
    cell.style.setProperty("--a", app.a);
    cell.style.setProperty("--b", app.b);
    cell.style.setProperty("--glow", app.glow);

    var ico = document.createElement("div");
    ico.className = "ico";
    ico.innerHTML = app.icon ? ICON[app.icon] : '<span class="lt">' + app.letter + "</span>";

    var name = document.createElement("div");
    name.className = "name";
    name.textContent = app.name;

    cell.appendChild(ico);
    cell.appendChild(name);
    frag.appendChild(cell);
    cell._ico = ico;
    cells.push(cell);

    // Magic Remote (ponteiro)
    cell.addEventListener("mouseenter", function () { if (canPoint()) setFocus(i); });
    cell.addEventListener("click", function () { if (canPoint()) { setFocus(i); launchCur(); } });
  });
  grid.appendChild(frag);
  for (var q = 0; q < APPS.length; q++) if (iconCache[APPS[q].name]) applyImage(q, iconCache[APPS[q].name]);
}
function buildGrid() { buildCells(); refreshFocus(); }
function rebuildGrid() {
  if (index > APPS.length - 1) index = APPS.length - 1;
  if (index < 0) index = 0;
  buildCells(); refreshFocus();
}
function setFocus(i) {
  if (i < 0 || i >= APPS.length) return;
  index = i; zone = "content"; cyRow = 0;
  refreshFocus();
}

// ---------- Cyber: cartoes, noticias, entradas ----------
function cardList() { return showNews ? ["cont", "news", "inp"] : ["cont", "inp"]; }

function mkCard(cls, eyebrow, title, sub) {
  var d = document.createElement("div");
  d.className = cls;
  d.innerHTML = '<div class="ceye"></div><div class="ctit"></div><div class="csb"></div>';
  d.childNodes[0].textContent = eyebrow;
  d.childNodes[1].textContent = title;
  d.childNodes[2].textContent = sub;
  return d;
}
function buildCyber() {
  var cc = $("ccards"), nc = $("ncards"), ic = $("icards");
  cc.innerHTML = ""; nc.innerHTML = ""; ic.innerHTML = "";
  var last = recall("hz_last", "");
  cardList().forEach(function (id, j) {
    var d;
    if (id === "cont") d = mkCard("ccard", "CONTINUAR", "Última reprodução", last ? last + " · retomar de onde parou" : "Abra um app para começar");
    else if (id === "news") d = NEWS.length ? mkCard("ccard", "NOTÍCIAS", NEWS[0].t, newsSub(NEWS[0])) : mkCard("ccard", "NOTÍCIAS", newsMsg(), "Abra a aba Notícias");
    else d = mkCard("ccard", "ENTRADAS", "HDMI 1 · HDMI 2", "TV ao vivo");
    d.addEventListener("mouseenter", function () { if (canPoint() && life === "cyber") { zone = "content"; cyRow = 1; cardIdx = j; refreshFocus(); } });
    d.addEventListener("click", function () { if (canPoint() && life === "cyber") { cardIdx = j; cardOK(); } });
    cc.appendChild(d);
  });
  if (!NEWS.length) {
    var e = mkCard("ncard", "NOTÍCIAS", newsMsg(), "Config. › Atualização › Atualizar notícias");
    e.insertBefore(document.createElement("div"), e.firstChild).className = "art";
    e.firstChild.style.background = "linear-gradient(135deg,#59c7ff,#1e5fa8)";
    nc.appendChild(e);
  }
  NEWS.forEach(function (n, j) {
    var d = mkCard("ncard", n.cat.toUpperCase(), n.t, newsSub(n));
    d.insertBefore(document.createElement("div"), d.firstChild).className = "art";
    d.firstChild.style.backgroundImage = artBg(n);
    d.addEventListener("mouseenter", function () { if (canPoint() && cyTab === "news") { zone = "content"; newsIdx = j; refreshFocus(); } });
    d.addEventListener("click", function () { if (canPoint() && cyTab === "news") { newsIdx = j; openReader(j); } });
    nc.appendChild(d);
  });
  INPUTS.forEach(function (n, j) {
    var d = mkCard("ncard inp", "ENTRADA", n.name, "OK para abrir");
    d.insertBefore(document.createElement("div"), d.firstChild).className = "art";
    d.firstChild.style.background = "linear-gradient(135deg," + n.a + "," + n.b + ")";
    d.addEventListener("mouseenter", function () { if (canPoint() && cyTab === "inputs") { zone = "content"; inIdx = j; refreshFocus(); } });
    d.addEventListener("click", function () { if (canPoint() && cyTab === "inputs") { inIdx = j; launchApp(INPUTS[j]); } });
    ic.appendChild(d);
  });
}
function cardOK() {
  var id = cardList()[cardIdx];
  if (id === "cont") {
    var nm = recall("hz_last", ""), app = APPS[index];
    for (var i = 0; i < APPS.length; i++) if (APPS[i].name === nm) app = APPS[i];
    if (app) launchApp(app);
  } else if (id === "news") { setTab("news"); zone = "content"; refreshFocus(); }
  else { setTab("inputs"); zone = "content"; refreshFocus(); }
}

// notícias ligadas/desligadas (Basic: painel ao lado; Cyber: aba + cartao)
function applyNews() {
  document.body.classList.toggle("news-on", showNews);
  if (tabList().indexOf(cyTab) < 0) cyTab = "home";
  $("cyber").setAttribute("data-tab", cyTab);
  buildTabs(); buildCyber();
  var n = hdrItems().length;
  if (hdrIndex > n - 1) hdrIndex = n - 1;
  if (cardIdx > cardList().length - 1) cardIdx = 0;
  refreshFocus();
}
function toggleNews() {
  showNews = !showNews;
  store("hz_news", showNews ? "1" : "0");
  applyNews(); refreshRows();
}
function buildNewsPanel() {
  var box = $("nlist");
  box.innerHTML = "";
  $("nstat").textContent = newsStatus();
  if (!NEWS.length) {
    var m = document.createElement("div");
    m.className = "nitem nmsg";
    m.textContent = newsMsg();
    box.appendChild(m);
    return;
  }
  if (bnIdx > NEWS.length - 1) bnIdx = NEWS.length - 1;
  if (bnTop > bnIdx) bnTop = bnIdx;
  if (bnIdx >= bnTop + BN_VIS) bnTop = bnIdx - BN_VIS + 1;
  for (var j = bnTop; j < Math.min(NEWS.length, bnTop + BN_VIS); j++) (function (j) {
    var n = NEWS[j], d = document.createElement("div");
    d.className = "nitem";
    d.innerHTML = '<i class="nth"></i><div class="ntx"><div class="ncat"></div><div class="nt"></div><div class="ns"></div></div>';
    d.firstChild.style.backgroundImage = artBg(n);
    d.childNodes[1].childNodes[0].textContent = n.cat.toUpperCase();
    d.childNodes[1].childNodes[1].textContent = n.t;
    d.childNodes[1].childNodes[2].textContent = newsSub(n);
    d.addEventListener("mouseenter", function () { if (canPoint() && life === "basic") { zone = "news"; bnIdx = j; refreshFocus(); } });
    d.addEventListener("click", function () { if (canPoint() && life === "basic") { bnIdx = j; openReader(j); } });
    box.appendChild(d);
  })(j);
}
function bnMove(d) {
  var n = bnIdx + d;
  if (n < 0 || n > NEWS.length - 1) return false;
  bnIdx = n;
  if (bnIdx < bnTop) bnTop = bnIdx;
  if (bnIdx >= bnTop + BN_VIS) bnTop = bnIdx - BN_VIS + 1;
  buildNewsPanel();
  return true;
}
function newsPanelKey(k) {
  if (k === 38) { if (!bnMove(-1)) toHeader(); }
  else if (k === 40) bnMove(1);
  else if (k === 37 || k === 461 || k === 27) { zone = "content"; }
  else if (k === 13) { if (NEWS.length) openReader(bnIdx); return; }
  refreshFocus();
}

// ---------- troca de lifestyle ----------
function setLife(k) {
  life = k;
  document.documentElement.setAttribute("data-life", k);
  loadLayout();
  index = 0; cyRow = 0; cyTab = "home"; zone = "content"; hdrIndex = 0;
  $("cyber").setAttribute("data-tab", "home");
  buildTabs(); buildCyber(); rebuildGrid();
}

// ---------- foco: um unico lugar pinta tudo ----------
function mark(box, idx, on) {
  var c = box.children;
  for (var i = 0; i < c.length; i++) c[i].classList.toggle("focus", on && i === idx);
}
function refreshFocus() {
  var home = screen === "home";
  var cy = life === "cyber";
  var appsOn = home && zone === "content" && (!cy || (cyTab === "home" && cyRow === 0));
  if (zone === "news" && (cy || !NEWS.length || !showNews)) zone = "content";
  var want = appsOn ? cells[index] : null;
  if (focusEl !== want) {
    if (focusEl) focusEl.classList.remove("focus");
    if (want) want.classList.add("focus");
    focusEl = want;
  }
  var L = hdrItems();
  for (var i = 0; i < L.length; i++) {
    L[i].el.classList.toggle("focus", home && zone === "header" && i === hdrIndex);
    if (L[i].tab) L[i].el.classList.toggle("on", L[i].tab === cyTab);
  }
  var inC = home && zone === "content" && cy;
  mark($("ccards"), cardIdx, inC && cyTab === "home" && cyRow === 1);
  mark($("ncards"), newsIdx, inC && cyTab === "news");
  mark($("icards"), inIdx, inC && cyTab === "inputs");
  mark($("nlist"), bnIdx - bnTop, home && zone === "news" && !cy && NEWS.length > 0);
  $("ncards").style.transform = "translate3d(" + (-Math.max(0, newsIdx - 1) * 544) + "px,0,0)";
  if (cy && APPS[index]) {                         // titulo e cor do fundo seguem o app em foco
    $("ctitle").textContent = APPS[index].name;
    document.documentElement.style.setProperty("--tint", APPS[index].glow);
  }
}

// ---------- teclas da tela inicial ----------
function headerKey(k) {
  var n = hdrItems().length;
  if (k === 37) { if (hdrIndex > 0) hdrAt(hdrIndex - 1); }
  else if (k === 39) { if (hdrIndex < n - 1) hdrAt(hdrIndex + 1); }
  else if (k === 40) { zone = "content"; refreshFocus(); }
  else if (k === 13) hdrOK();
  else if (k === 461 || k === 27) {
    if (life === "cyber" && cyTab !== "home") { setTab("home"); hdrIndex = 0; refreshFocus(); }
    else leaveApp();
  }
}
function basicKey(k) {
  var last = APPS.length - 1, lastRow = Math.floor(last / COLS), row = Math.floor(index / COLS);
  if (k === 37) { if (index % COLS > 0) setFocus(index - 1); }
  else if (k === 39) {
    if (index % COLS < COLS - 1 && index < last) setFocus(index + 1);
    else if (showNews && NEWS.length) { zone = "news"; refreshFocus(); }       // da ultima coluna para a lista de noticias
  }
  else if (k === 38) { if (row > 0) setFocus(index - COLS); else toHeader(); }
  else if (k === 40) {
    if (index + COLS <= last) setFocus(index + COLS);
    else if (row < lastRow) setFocus(last);
  }
  else if (k === 13) launchCur();
  else if (k === 461 || k === 27) leaveApp();
}
function cyberKey(k) {
  var n;
  if (cyTab === "home") {
    if (cyRow === 0) {
      if (k === 37) { if (index > 0) setFocus(index - 1); }
      else if (k === 39) { if (index < APPS.length - 1) setFocus(index + 1); }
      else if (k === 40) { cyRow = 1; refreshFocus(); }
      else if (k === 38) toHeader();
      else if (k === 13) launchCur();
      else if (k === 461 || k === 27) leaveApp();
    } else {
      n = cardList().length;
      if (k === 37) { if (cardIdx > 0) { cardIdx--; refreshFocus(); } }
      else if (k === 39) { if (cardIdx < n - 1) { cardIdx++; refreshFocus(); } }
      else if (k === 38 || k === 461 || k === 27) { cyRow = 0; refreshFocus(); }
      else if (k === 13) cardOK();
    }
    return;
  }
  var isNews = cyTab === "news";
  n = isNews ? NEWS.length : INPUTS.length;
  var cur = isNews ? newsIdx : inIdx;
  if (k === 37) cur = Math.max(0, cur - 1);
  else if (k === 39) cur = Math.max(0, Math.min(n - 1, cur + 1));
  else if (k === 38) { toHeader(); return; }
  else if (k === 13) { if (isNews) { if (NEWS.length) openReader(newsIdx); else loadNews(true); } else launchApp(INPUTS[inIdx]); return; }
  else if (k === 461 || k === 27) { setTab("home"); return; }
  if (isNews) newsIdx = cur; else inIdx = cur;
  refreshFocus();
}
function homeKey(k) {
  if (zone === "header") headerKey(k);
  else if (zone === "news" && life === "basic") newsPanelKey(k);
  else if (life === "cyber") cyberKey(k);
  else basicKey(k);
}

// ---------- abrir apps ----------
var toastTimer = null;
function toast(msg) {
  var t = $("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function () { t.classList.remove("show"); }, 3200);
}

var bridges = [];   // guarda as chamadas ate a TV responder (senao o navegador pode descartar antes)
function luna(uri, payload, onFail, onOk) {
  try {
    var bridge = new PalmServiceBridge();
    bridges.push(bridge);
    if (bridges.length > 24) bridges.shift();
    bridge.onservicecallback = function (msg) {
      var res = {};
      try { res = JSON.parse(msg); } catch (e) {}
      if (res.returnValue === false) { if (onFail) onFail(res); }
      else if (onOk) { onOk(res); }
    };
    bridge.call(uri, JSON.stringify(payload));
  } catch (e) {
    if (onFail) onFail({ errorText: "fora da TV" });
  }
}

function launchApp(app, el) {
  if (el) { el.classList.add("press"); setTimeout(function () { el.classList.remove("press"); }, 220); }
  var id = app.rid || app.id;     // rid = ID real achado na TV pelo nome
  var payload = app.url && !app.rid
    ? { id: "com.webos.app.browser", params: { target: app.url } }
    : { id: id };
  luna("luna://com.webos.applicationManager/launch", payload, function () {
    toast(app.name + " não abriu. Aperte o botão azul para ver o diagnóstico.");
  });
  if (app.letter || app.icon) { store("hz_last", app.name); }
}
function launchCur() { if (APPS[index]) launchApp(APPS[index], cells[index]); }

// Sai do app de verdade (fecha), assim a entrada toca de novo na proxima vez
function leaveApp() {
  try { if (window.webOS && webOS.platformBack) { webOS.platformBack(); return; } } catch (e) {}
  try { window.close(); } catch (e) {}
  setTimeout(function () {
    luna("luna://com.webos.applicationManager/launch", { id: "com.webos.app.home" });
  }, 500);
}

