var pk = null, vcards = [], vopts = [];

// Seletor generico (Visual e Lifestyle): cartoes com previa ao vivo + opcoes embaixo.
//  cfg = { title, wide, items:[{key,name,desc,sw}], cur(), preview(key), commit(key), opts:[{label(), toggle()}] }
function openPicker(cfg) {
  pk = cfg; cfg.idx = 0; cfg.area = "cards"; cfg.oi = 0;
  for (var i = 0; i < cfg.items.length; i++) if (cfg.items[i].key === cfg.cur()) cfg.idx = i;
  $("vtitle").textContent = cfg.title;
  var box = $("vcards"); box.innerHTML = ""; vcards = [];
  box.className = "vcards" + (cfg.wide ? " wide" : "");
  cfg.items.forEach(function (s, i) {
    var c = document.createElement("div");
    c.className = "vcard";
    c.innerHTML = '<div class="vsw"></div><div class="vname"></div><div class="vdesc"></div>';
    c.childNodes[0].style.background = s.sw;
    c.childNodes[1].textContent = s.name;
    c.childNodes[2].textContent = s.desc || "";
    c.addEventListener("mouseenter", function () { if (screen === "picker") { pk.area = "cards"; pickerSet(i); } });
    c.addEventListener("click", function () { if (screen === "picker") { pickerSet(i); pickerClose(true); } });
    box.appendChild(c); vcards.push(c);
  });
  var ob = $("vopts"); ob.innerHTML = ""; vopts = [];
  (cfg.opts || []).forEach(function (o, i) {
    var d = document.createElement("div");
    d.className = "vopt";
    d.addEventListener("mouseenter", function () { if (screen === "picker") { pk.area = "opts"; pk.oi = i; pickerRefresh(); } });
    d.addEventListener("click", function () { if (screen === "picker") { pk.area = "opts"; pk.oi = i; o.toggle(); pickerRefresh(); } });
    ob.appendChild(d); vopts.push(d);
  });
  push("picker");
  pickerRefresh();
}
function pickerRefresh() {
  if (!pk) return;
  for (var i = 0; i < vcards.length; i++) {
    vcards[i].classList.toggle("focus", pk.area === "cards" && i === pk.idx);
    vcards[i].classList.toggle("cur", pk.items[i].key === pk.cur());
  }
  for (var j = 0; j < vopts.length; j++) {
    vopts[j].textContent = pk.opts[j].label();
    vopts[j].classList.toggle("focus", pk.area === "opts" && j === pk.oi);
  }
  $("vhint").textContent = pk.area === "cards"
    ? "◀ ▶ escolhe  ·  OK confirma  ·  Voltar cancela" + (vopts.length ? "  ·  ▼ opções" : "")
    : "▲ ▼ escolhe  ·  OK liga/desliga  ·  Voltar fecha";
}
function pickerSet(i) {
  if (i < 0 || i >= pk.items.length) return;
  pk.idx = i;
  pk.preview(pk.items[i].key);          // previa ao vivo
  pickerRefresh();
}
function pickerClose(commit) {
  var p = pk; pk = null;
  if (commit) p.commit(p.items[p.idx].key);
  else p.preview(p.cur());              // cancelou: volta ao que estava salvo
  if (p.after) p.after();
  pop(); refreshRows(); refreshFocus();
}
function pickerKey(k) {
  var n = pk.items.length, no = vopts.length;
  if (pk.area === "cards") {
    if (k === 37) pickerSet(pk.idx - 1);
    else if (k === 39) pickerSet(pk.idx + 1);
    else if (k === 40) { if (no) { pk.area = "opts"; pk.oi = 0; pickerRefresh(); } }
    else if (k === 13) pickerClose(true);
    else if (k === 461 || k === 27) pickerClose(false);
  } else {
    if (k === 38) { if (pk.oi > 0) pk.oi--; else pk.area = "cards"; pickerRefresh(); }
    else if (k === 40) { if (pk.oi < no - 1) { pk.oi++; pickerRefresh(); } }
    else if (k === 13 || k === 37 || k === 39) { pk.opts[pk.oi].toggle(); pickerRefresh(); }
    else if (k === 461 || k === 27) pickerClose(false);
  }
}

function toggleIntro() {
  introOn = !introOn;
  store("hz_intro", introOn ? "1" : "0");
  refreshRows();
}
function renderIntroOpt() { pickerRefresh(); }

function openVisual() {
  if (screen === "picker" || screen === "org") return;
  openPicker({
    title: "Visual", wide: false,
    items: STYLES.map(function (s) { return { key: s.key, name: s.name, sw: s.sw, desc: "" }; }),
    cur: function () { return savedStyle; },
    preview: function (k) { applyStyle(k); },
    commit: function (k) { savedStyle = k; store("hz_style", k); applyStyle(k); },
    opts: [{ label: function () { return "Animação de entrada: " + (introOn ? "ligada" : "desligada"); }, toggle: toggleIntro }]
  });
}
function openLife() {
  if (screen === "picker" || screen === "org") return;
  var z0 = zone, tid = (hdrItems()[hdrIndex] || {}).el ? hdrItems()[hdrIndex].el.id : null;
  openPicker({
    after: function () {                  // trocar de lifestyle muda a barra do topo: volta para o mesmo botao
      zone = z0;
      var L = hdrItems(); hdrIndex = 0;
      for (var i = 0; i < L.length; i++) if (L[i].el.id === tid) hdrIndex = i;
    },
    title: "Lifestyle", wide: true,
    items: LIFE_KEYS.map(function (k) { return { key: k, name: LIFE[k].name, sw: LIFE[k].sw, desc: LIFE[k].desc }; }),
    cur: function () { return savedLife; },
    preview: function (k) { if (k !== life) setLife(k); },
    commit: function (k) { savedLife = k; store("hz_life", k); if (k !== life) setLife(k); },
    opts: [{ label: function () { return "Mostrar notícias: " + (showNews ? "sim" : "não"); }, toggle: toggleNews }]
  });
}

// Configuracoes: Com som -> Sem som -> Desligada
function cycleIntro(d) {
  var m = !introOn ? 2 : (introSnd ? 0 : 1);
  m = (m + (d || 1) + 3) % 3;
  introOn = m !== 2;
  introSnd = m === 0;
  store("hz_intro", introOn ? "1" : "0");
  store("hz_introsnd", introSnd ? "1" : "0");
  renderIntroOpt(); refreshRows();
}
