// ============================================================
// ORGANIZAR APPS: escolher quais ficam na tela inicial e em que ordem
//   OK num app da tela -> Mover / Remover.   OK num app disponivel -> adiciona.
//   Limite: maxApps() (15). Fica salvo na TV (localStorage).
// ============================================================
var orgOpen = false;
var oSec = 0;            // 0 = na tela inicial, 1 = disponiveis, 2 = botao restaurar
var oIdx = 0;
var oMode = "nav";       // "nav", "pop" (menu Mover/Remover) ou "move"
var pIdx = 0;
var oDirty = false;
var oBackup = [];        // copia da lista ao abrir: "Voltar" volta para ela, "Confirmar" salva a nova

function saveLayout() { oDirty = true; }          // so marca; quem grava de verdade e o botao Confirmar
function persistLayout() {
  store(LIFE[life].key, JSON.stringify(APPS.map(function (a) { return a.name; })));
}

function loadLayout() {
  var names = [];
  try { names = JSON.parse(recall(LIFE[life].key, "null")) || []; } catch (e) { names = []; }
  APPS = [];
  names.forEach(function (n) {
    for (var i = 0; i < CATALOG.length; i++) {
      if (CATALOG[i].name === n && APPS.indexOf(CATALOG[i]) < 0 && APPS.length < maxApps()) { APPS.push(CATALOG[i]); break; }
    }
  });
  if (!APPS.length) resetLayout(true);
}

function resetLayout(silent) {
  APPS = [];
  LIFE[life].def.forEach(function (n) {
    for (var i = 0; i < CATALOG.length; i++) if (CATALOG[i].name === n) { APPS.push(CATALOG[i]); break; }
  });
  if (!silent) saveLayout();
}

function availApps() { return CATALOG.filter(function (a) { return APPS.indexOf(a) < 0; }); }

function popOpts() { return APPS.length > 1 ? ["Mover", "Remover", "Cancelar"] : ["Mover", "Cancelar"]; }

function chipFor(app, num) {
  var c = document.createElement("div");
  c.className = "chip2";
  c.style.setProperty("--a", app.a); c.style.setProperty("--b", app.b);
  var ic = document.createElement("div"); ic.className = "cico";
  if (iconCache[app.name]) { var im = document.createElement("img"); im.src = iconCache[app.name]; ic.appendChild(im); }
  else ic.innerHTML = app.icon ? ICON[app.icon] : '<span class="lt">' + app.letter + "</span>";
  var nm = document.createElement("div"); nm.className = "cname"; nm.textContent = app.name;
  c.appendChild(ic); c.appendChild(nm);
  if (num) { var n = document.createElement("div"); n.className = "cnum"; n.textContent = num; c.appendChild(n); }
  return c;
}

function renderOrg() {
  var home = $("ohome"), av = $("oavail"), list = availApps();
  home.innerHTML = ""; av.innerHTML = "";
  APPS.forEach(function (app, i) {
    var c = chipFor(app, i + 1);
    if (oSec === 0 && oIdx === i) c.classList.add(oMode === "move" ? "grab" : "focus");
    c.addEventListener("mouseenter", function () { if (orgOpen && oMode === "nav") { oSec = 0; oIdx = i; renderOrg(); } });
    c.addEventListener("click", function () { if (orgOpen && oMode === "nav") { oSec = 0; oIdx = i; orgOK(); } });
    home.appendChild(c);
  });
  list.forEach(function (app, i) {
    var c = chipFor(app, "");
    if (oSec === 1 && oIdx === i) c.classList.add("focus");
    c.addEventListener("mouseenter", function () { if (orgOpen && oMode === "nav") { oSec = 1; oIdx = i; renderOrg(); } });
    c.addEventListener("click", function () { if (orgOpen && oMode === "nav") { oSec = 1; oIdx = i; orgOK(); } });
    av.appendChild(c);
  });
  $("oavh").style.display = list.length ? "" : "none";
  var cnt = $("ocount");
  cnt.textContent = APPS.length + " de " + maxApps();
  cnt.className = "ocount" + (APPS.length >= maxApps() ? " full" : "");
  $("oreset").classList.toggle("focus", oSec === 2 && oIdx === 0);
  $("ocfm").classList.toggle("focus", oSec === 2 && oIdx === 1);

  var pop = $("opop");
  if (oMode === "pop") {
    pop.innerHTML = "";
    popOpts().forEach(function (t, i) {
      var d = document.createElement("div"); d.className = "popt" + (i === pIdx ? " focus" : ""); d.textContent = t;
      d.addEventListener("click", function () { pIdx = i; orgOK(); });
      pop.appendChild(d);
    });
    pop.classList.add("show");
  } else pop.classList.remove("show");

  $("ohint").textContent =
    oMode === "move" ? "◀ ▶ ▲ ▼ move o app  ·  OK solta" :
    oMode === "pop"  ? "▲ ▼ escolhe  ·  OK confirma  ·  Voltar cancela" :
    "◀ ▶ ▲ ▼ escolhe  ·  OK num app: mover ou remover  ·  OK num disponível: adiciona  ·  Confirmar salva  ·  Voltar cancela";
}

function openOrg() {
  if (screen === "picker" || screen === "org") return;
  orgOpen = true; oSec = 0; oIdx = 0; oMode = "nav"; oDirty = false;
  oBackup = APPS.slice();
  $("olife").textContent = "· " + LIFE[life].name;
  push("org");
  renderOrg();
}

// confirm = true salva a nova ordem; senao descarta o que foi mexido
function closeOrg(confirm) {
  orgOpen = false; oMode = "nav";
  if (confirm) {
    if (oDirty) { persistLayout(); rebuildGrid(); toast("Alterações salvas."); }
  } else if (oDirty) {
    APPS = oBackup.slice();
  }
  oDirty = false;
  pop(); refreshRows(); refreshFocus();       // volta para quem abriu (home ou Configuracoes)
}

function orgOK() {
  if (oMode === "pop") {
    var opt = popOpts()[pIdx];
    if (opt === "Mover") oMode = "move";
    else if (opt === "Remover") {
      APPS.splice(oIdx, 1);
      if (oIdx > APPS.length - 1) oIdx = APPS.length - 1;
      saveLayout(); oMode = "nav";
    } else oMode = "nav";
  } else if (oMode === "move") {
    oMode = "nav";
  } else if (oSec === 0) {
    oMode = "pop"; pIdx = 0;
  } else if (oSec === 1) {
    var list = availApps();
    if (APPS.length >= maxApps()) { toast("Limite de " + maxApps() + " apps. Remova um para adicionar outro."); return; }
    if (list[oIdx]) {
      APPS.push(list[oIdx]); saveLayout();
      var left = availApps().length;
      if (!left) { oSec = 0; oIdx = APPS.length - 1; }
      else if (oIdx > left - 1) oIdx = left - 1;
    }
  } else if (oIdx === 1) {
    closeOrg(true); return;
  } else {
    resetLayout(false); oSec = 0; oIdx = 0;
    toast("Padrão restaurado. Aperte Confirmar para salvar.");
  }
  renderOrg();
}

// Magic Remote nos botoes de baixo (Restaurar padrao / Confirmar)
[["oreset", 0], ["ocfm", 1]].forEach(function (b) {
  var el = $(b[0]);
  el.addEventListener("mouseenter", function () { if (orgOpen && oMode === "nav") { oSec = 2; oIdx = b[1]; renderOrg(); } });
  el.addEventListener("click", function () { if (orgOpen && oMode === "nav") { oSec = 2; oIdx = b[1]; orgOK(); } });
});

function orgKey(k) {
  if (oMode === "pop") {
    var n = popOpts().length;
    if (k === 38) { if (pIdx > 0) pIdx--; }
    else if (k === 40) { if (pIdx < n - 1) pIdx++; }
    else if (k === 13) { orgOK(); return; }
    else if (k === 461 || k === 27) oMode = "nav";
    renderOrg(); return;
  }
  if (oMode === "move") {
    var t = oIdx;
    if (k === 37) t = oIdx - 1; else if (k === 39) t = oIdx + 1;
    else if (k === 38) t = oIdx - COLS; else if (k === 40) t = oIdx + COLS;
    if ((k === 37 || k === 38 || k === 39 || k === 40)) {
      if (t >= 0 && t < APPS.length && t !== oIdx) {
        var tmp = APPS[oIdx]; APPS[oIdx] = APPS[t]; APPS[t] = tmp;
        oIdx = t; saveLayout();
      }
    } else if (k === 13 || k === 461 || k === 27) oMode = "nav";
    renderOrg(); return;
  }

  var avn = availApps().length;
  var len = oSec === 0 ? APPS.length : (oSec === 1 ? avn : 2);
  if (k === 37) { if (oIdx > 0) oIdx--; }
  else if (k === 39) { if (oIdx < len - 1) oIdx++; }
  else if (k === 38) {
    if (oSec === 2) { if (avn) { oSec = 1; oIdx = Math.floor((avn - 1) / COLS) * COLS; } else { oSec = 0; oIdx = Math.floor((APPS.length - 1) / COLS) * COLS; } }
    else if (oIdx >= COLS) oIdx -= COLS;
    else if (oSec === 1) { var col = oIdx % COLS; oSec = 0; oIdx = Math.min(APPS.length - 1, Math.floor((APPS.length - 1) / COLS) * COLS + col); }
  }
  else if (k === 40) {
    if (oSec < 2 && oIdx + COLS < len) oIdx += COLS;
    else if (oSec < 2 && Math.floor(oIdx / COLS) < Math.floor((len - 1) / COLS)) oIdx = len - 1;
    else if (oSec === 0 && avn) { oSec = 1; oIdx = Math.min(avn - 1, oIdx % COLS); }
    else if (oSec < 2) { oSec = 2; oIdx = 1; }
  }
  else if (k === 13) { orgOK(); return; }
  else if (k === 461 || k === 27) { closeOrg(false); return; }
  renderOrg();
}

// ============================================================
// CONTROLE REMOTO - um unico tratador; cada tela cuida das suas teclas.
//   Voltar (461/Esc) sempre sobe um nivel.
//   Atalhos: vermelho = Configuracoes, verde = Lifestyle, amarelo = Visual, azul = diagnostico
// ============================================================
var KEYS = {
  reader: function (k) { readerKey(k); },
  prompt: function (k) { promptKey(k); },
  home: function (k) { homeKey(k); },
  settings: function (k) { settingsKey(k); },
  picker: function (k) { pickerKey(k); },
  org: function (k) { orgKey(k); }
};

function shortcut(k) {
  if (screen !== "home" && screen !== "settings") return false;
  if (k === 403) { if (screen === "home") openSettings(); return true; }
  if (k === 404) { openLife(); return true; }
  if (k === 405) { openVisual(); return true; }
  return false;
}

document.addEventListener("keydown", function (e) {
  var k = e.keyCode;

  if (k === 406) { toggleDebug(); return; }            // botao azul: diagnostico dos icones

  if (!introDone) {                       // qualquer tecla pula a entrada (depois de 1,2 s)
    if (Date.now() - introStart < 1200) return;
    if (k === 461 || k === 27) { leaveApp(); return; }
    endIntro();
    return;
  }

  if (shortcut(k)) return;
  if (KEYS[screen]) KEYS[screen](k);
});

// ============================================================
// RELOGIO E SAUDACAO (sem depender do idioma da TV)
// ============================================================
var WD = ["Domingo", "Segunda-feira", "Terça-feira", "Quarta-feira", "Quinta-feira", "Sexta-feira", "Sábado"];
var MO = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
var lastClock = "", lastAp = "", lastDate = "", lastHello = "";
var clock24 = true;           // true = 24 horas, false = 12 horas (AM/PM)

function tick() {
  var d = new Date();
  var h = d.getHours();
  var mi = ("0" + d.getMinutes()).slice(-2);
  var clock, ap = "";
  if (clock24) clock = ("0" + h).slice(-2) + ":" + mi;
  else { ap = h < 12 ? "AM" : "PM"; clock = (h % 12 || 12) + ":" + mi; }
  var date = WD[d.getDay()] + ", " + d.getDate() + " de " + MO[d.getMonth()];
  var hello = h < 12 ? "Bom dia" : (h < 18 ? "Boa tarde" : "Boa noite");

  if (clock !== lastClock) { $("clock").textContent = clock; lastClock = clock; }
  if (ap !== lastAp) { $("ampm").textContent = ap; lastAp = ap; }
  if (date !== lastDate)   { $("date").textContent = date;   lastDate = date; }
  if (hello !== lastHello) { $("hello").textContent = hello; lastHello = hello; }
}

// ============================================================
// ENTRADA: fundo branco, o H forma "Horizon", pico de luz, aparece "TV"
// So usa transform e opacity (leve para a TV). As animacoes so comecam
// depois que a tela ja foi pintada, e a entrada termina quando a ultima
// animacao acaba - nao num tempo fixo que pode cortar tudo no meio.
// ============================================================
function buildIntroLetters() {
  var box = $("letters");
  var word = "Horizon";
  var c1 = [0x2f, 0x78, 0xee], c2 = [0x12, 0xa5, 0x94];
  for (var k = 0; k < word.length; k++) {
    var t = k / (word.length - 1);
    var rgb = [0, 1, 2].map(function (j) { return Math.round(c1[j] + (c2[j] - c1[j]) * t); });
    var s = document.createElement("span");
    s.className = k === 0 ? "l h" : "l r";
    s.textContent = word.charAt(k);
    s.style.color = "rgb(" + rgb.join(",") + ")";           // cor solida por letra (sem recorte de degrade, que falhava com animacao)
    if (k > 0) s.style.animationDelay = (1.3 + (k - 1) * 0.18).toFixed(2) + "s";   // uma letra a cada 0,18 s
    box.appendChild(s);
  }

  var tv = document.querySelector(".i-tv");
  var onEnd = function () {
    if (introDone) return;
    clearTimeout(introTimer);
    introTimer = setTimeout(endIntro, 1700);                // segura o logo completo ate o som acabar
  };
  tv.addEventListener("animationend", onEnd);
  tv.addEventListener("webkitAnimationEnd", onEnd);
}

// ---- som da entrada (intro.mp3, sintetizado, ~6,5 s; o climax cai em 3,2 s, junto do pico de luz) ----
var introAudio = null;
var introSnd = true;
function prepAudio() {
  try { introAudio = new Audio("intro.mp3"); introAudio.preload = "auto"; introAudio.volume = 0.9; }
  catch (e) { introAudio = null; }
}
function playIntroSound() {
  if (!introAudio || !introSnd) return;
  try {
    introAudio.currentTime = 0;
    var p = introAudio.play();
    if (p && p.catch) p.catch(function () {});
  } catch (e) {}
}
function stopIntroSound() {
  if (!introAudio) return;
  try { introAudio.pause(); introAudio.currentTime = 0; } catch (e) {}
}

function startIntro() {
  var intro = $("intro");
  stopIntroSound();
  clearTimeout(introTimer);
  introDone = false;
  introStart = Date.now();
  document.body.classList.remove("ready");
  intro.style.display = "flex";
  intro.classList.remove("out");
  intro.classList.remove("play");
  void intro.offsetWidth;                                   // forca recomecar do zero
  var go = function () {
    introStart = Date.now();
    intro.classList.add("play");
    playIntroSound();
    introTimer = setTimeout(endIntro, 9500);                // seguranca, se algo travar
  };
  // espera a primeira pintura da tela branca antes de animar
  if (window.requestAnimationFrame) requestAnimationFrame(function () { requestAnimationFrame(go); });
  else setTimeout(go, 60);
}

function endIntro() {
  if (introDone) return;
  introDone = true;
  clearTimeout(introTimer);
  stopIntroSound();                                         // se pulou a entrada, corta o som
  var intro = $("intro");
  intro.classList.add("out");
  document.body.classList.add("ready");
  setTimeout(function () { if (introDone) intro.style.display = "none"; }, 750);
}

// Voltar para o launcher (o app ficou em segundo plano): toca a entrada de novo
var lastReplay = 0;
var wasHidden = false;
function replay() {
  var now = Date.now();
  if (now - lastReplay < 1000) return;
  lastReplay = now;
  closeAll();
  zone = "content"; index = 0; cyRow = 0; cyTab = "home"; hdrIndex = 0;
  $("cyber").setAttribute("data-tab", "home");
  refreshFocus();
  if (introOn) startIntro();
}

function onVis() {
  var hidden = document.hidden || document.webkitHidden;
  if (hidden) wasHidden = true;
  else if (wasHidden) { wasHidden = false; replay(); }
}
document.addEventListener("visibilitychange", onVis);
document.addEventListener("webkitvisibilitychange", onVis);
document.addEventListener("webOSRelaunch", replay);
window.addEventListener("pageshow", function (e) { if (e.persisted) replay(); });

// Detector que nao depende de eventos: se o app ficou congelado em segundo plano
// (a TV para os timers), o relogio de 1 s "pula". Ao voltar, toca a entrada.
var lastBeat = Date.now();
setInterval(function () {
  var now = Date.now();
  if (introDone && now - lastBeat > 3000 && !(document.hidden || document.webkitHidden)) replay();
  lastBeat = now;
}, 1000);

