// ICONES REAIS
// Ordem: 1) imagem sua em logos/<nome>.png   2) icone do app instalado na TV
//        3) o que foi achado da ultima vez     4) icone desenhado (degrade)
// A TV e consultada por listLaunchPoints (o mesmo que a tela inicial da LG usa)
// e por listApps; o app e achado pelo ID, depois pelo nome, depois por pedaco do ID.
// ============================================================
var LOGO = {
  "Netflix": "netflix", "YouTube": "youtube", "Prime Video": "primevideo",
  "Globoplay": "globoplay", "YouTube Music": "youtubemusic",
  "Disney+": "disneyplus", "Spotify": "spotify",
  "Max": "max", "Apple TV": "appletv", "Paramount+": "paramountplus",
  "Crunchyroll": "crunchyroll", "Twitch": "twitch", "Pluto TV": "plutotv",
  "Deezer": "deezer", "Plex": "plex"
};

var applied = {};      // indice -> src ja aplicado
var dbg = { lp: "pendente", la: "pendente", apps: [] };

function fileUrl(p, base) {
  if (!p) return null;
  if (/^(file|https?|data):/i.test(p)) return p;
  if (p.charAt(0) !== "/" && base) p = base.replace(/\/$/, "") + "/" + p;
  return p.charAt(0) === "/" ? "file://" + p : p;
}

function tryImages(list, done) {
  var n = 0;
  (function next() {
    if (n >= list.length) { done(null); return; }
    var img = new Image();
    var src = list[n++];
    img.onload = function () { done(src); };
    img.onerror = next;
    img.src = src;
  })();
}

function applyImage(i, src) {
  if (applied[i] === src) return;
  applied[i] = src;
  var ico = cells[i]._ico;
  ico.classList.add("has-img");
  ico.innerHTML = "";
