  img.src = src;
  ico.appendChild(img);
}

// procura o app da lista dentro do que a TV devolveu
function findTv(app, byId, byTitle, all) {
  if (app.id && byId[app.id]) return byId[app.id];
  var t = app.titles || [];
  for (var i = 0; i < t.length; i++) if (byTitle[t[i]]) return byTitle[t[i]];
  var h = app.hints || [];
  for (var j = 0; j < h.length; j++) {
    for (var k = 0; k < all.length; k++) {
      var id = (all[k].id || "").toLowerCase();
      if (id.indexOf(h[j]) !== -1 && id.indexOf("alexa") === -1 && id.indexOf("kids") === -1) return all[k];
    }
  }
  return null;
}

var tvAll = [], tvById = {}, tvByTitle = {}, tvReady = false, iconCache = {};

// ------------------------------------------------------------
// ICONES OFICIAIS AUTOMATICOS
// A LG nao deixa apps instalados por voce lerem os icones da propria TV
// (listApps/listLaunchPoints sao bloqueados). Entao o launcher busca o
// icone oficial do app na App Store (Apple iTunes API, gratuita) so na
// primeira vez e guarda o endereco. Precisa da TV na internet.
// [bundle id do app no iOS, nome para buscar se o id falhar]
// ------------------------------------------------------------
var OFFICIAL = {
  "Netflix":       ["com.netflix.Netflix", "netflix"],
  "YouTube":       ["com.google.ios.youtube", "youtube"],
  "Prime Video":   ["com.amazon.aiv.AIVApp", "prime video"],
  "Globoplay":     ["com.globo.globoplay", "globoplay"],
  "YouTube Music": ["com.google.ios.youtubemusic", "youtube music"],
  "Disney+":       ["com.disney.disneyplus", "disney+"],
  "Spotify":       ["com.spotify.client", "spotify"],
  "Max":           ["com.hbo.hbonow", "max"],
  "Apple TV":      ["com.apple.TVWatchList", "apple tv"],
  "Paramount+":    ["com.cbsvideo.app", "paramount+"],
  "Crunchyroll":   ["com.crunchyroll.iphone", "crunchyroll"],
  "Twitch":        ["tv.twitch", "twitch"],
  "Pluto TV":      ["tv.pluto.ios", "pluto tv"],
  "Deezer":        ["com.deezer.Deezer", "deezer"],
  "Plex":          ["com.plexapp.plex", "plex"]
};
var itN = 0, itQ = [], itBusy = false;

function itJsonp(url, cb) {
  var name = "__it" + (++itN), sc = document.createElement("script"), done = false;
  function fin(r) {
    if (done) return;
    done = true;
    try { delete window[name]; } catch (e) { window[name] = undefined; }
    if (sc.parentNode) sc.parentNode.removeChild(sc);
    cb(r);
  }
  window[name] = function (r) { fin(r); };
  sc.onerror = function () { fin(null); };
  setTimeout(function () { fin(null); }, 7000);
  sc.src = url + (url.indexOf("?") < 0 ? "?" : "&") + "callback=" + name;
  document.head.appendChild(sc);
}

function artFrom(r, term) {
  var res = (r && r.results) || [];
  for (var i = 0; i < res.length; i++) {
    var n = (res[i].trackName || "").toLowerCase();
    if (res[i].artworkUrl512 && (!term || n.indexOf(term) !== -1)) return res[i].artworkUrl512;
  }
  return null;
}

function fetchOfficial(app, cb) {
  var o = OFFICIAL[app.name];
  if (!o) { cb(null); return; }
  itQ.push({ app: app, o: o, cb: cb });
  if (!itBusy) runItQ();
}
function runItQ() {
  var j = itQ.shift();
  if (!j) { itBusy = false; return; }
  itBusy = true;
  var next = function (u) { j.cb(u); setTimeout(runItQ, 450); };     // um pedido por vez (a API limita ~20/min)
  itJsonp("https://itunes.apple.com/lookup?bundleId=" + encodeURIComponent(j.o[0]) + "&country=br", function (r) {
    var u = artFrom(r, null);
    if (u) { next(u); return; }
    itJsonp("https://itunes.apple.com/search?term=" + encodeURIComponent(j.o[1]) + "&entity=software&country=br&limit=5", function (r2) {
      next(artFrom(r2, j.o[1]));
    });
  });
}



function logosFor(app) {
  var slug = LOGO[app.name], list = [];
  if (slug) list.push("logos/" + slug + ".png", "logos/" + slug + ".jpg", "logos/" + slug + ".svg");
  return list;
}

function tvAdd(a) {
  if (!a || !a.id) return;
  var cur = tvById[a.id];
  if (cur) {                                   // junta o que um e outro trouxeram
    for (var k in a) if (a[k] && !cur[k]) cur[k] = a[k];
    return;
  }
  tvById[a.id] = a;
  tvAll.push(a);
  var ti = (a.title || "").toLowerCase();
  if (ti && !tvByTitle[ti]) tvByTitle[ti] = a;
}

// procura a imagem de todos os apps do catalogo (os da tela e os que da pra adicionar)
function resolveIcons() {
  dbg.apps = [];
  CATALOG.forEach(function (app) {
    var rec = { name: app.name, found: "-", tried: 0, shown: "-" };
    dbg.apps.push(rec);
    if (!LOGO[app.name]) return;                // Navegador/Entradas/etc. ficam com o desenho

    var tv = tvReady ? findTv(app, tvById, tvByTitle, tvAll) : null;
    var list = logosFor(app);
    if (tv) {
      rec.found = tv.id + " (" + (tv.title || "?") + ")";
      if (tv.id !== app.id && app.id) app.rid = tv.id;            // ID certo, caso o do app.js esteja errado
      else if (!app.id) app.rid = tv.id;
      var base = tv.folderPath || "";
      if (tv.largeIcon) list.push(fileUrl(tv.largeIcon, base));
      if (tv.icon) list.push(fileUrl(tv.icon, base));
    } else {
      rec.found = tvReady ? "nao achei na TV" : "TV ainda nao respondeu";
    }
    if (iconCache[app.name]) list.push(iconCache[app.name]);
    rec.tried = list.length;

    function ok(src) {
      rec.shown = src;
      iconCache[app.name] = src;
      store("hz_icons", JSON.stringify(iconCache));
      var j = APPS.indexOf(app);
      if (j >= 0 && cells[j]) applyImage(j, src);
      if (orgOpen) renderOrg();
      if (dbgEl && dbgEl.style.display === "block") renderDebug();
    }
    tryImages(list, function (src) {
      if (src) { ok(src); return; }
      // nada local/da TV: busca o icone oficial na App Store (so uma vez por app)
      var lastFail = parseInt(recall("hz_nf_" + app.name, "0"), 10) || 0;      // se falhou nas ultimas 24 h, nao insiste
      if (!tvReady || app._off || !OFFICIAL[app.name] || Date.now() - lastFail < 86400000) {
        rec.shown = "desenhado (nenhuma imagem carregou)";
        if (dbgEl && dbgEl.style.display === "block") renderDebug();
        return;
      }
      app._off = true;
      rec.shown = "buscando icone oficial...";
      fetchOfficial(app, function (u) {
        if (!u) { store("hz_nf_" + app.name, String(Date.now())); rec.shown = "desenhado (sem internet ou nao achei)"; if (dbgEl && dbgEl.style.display === "block") renderDebug(); return; }
        tryImages([u], function (ok2) {
          if (ok2) ok(ok2);
          else { rec.shown = "desenhado (icone oficial nao carregou)"; if (dbgEl && dbgEl.style.display === "block") renderDebug(); }
        });
      });
    });
  });
}

function loadIcons() {
  var waiting = 2, finished = false;

  function settle() {
    if (finished) return;
    finished = true;
    tvReady = true;
    resolveIcons();
  }
  function oneDone() { waiting--; if (waiting <= 0) settle(); }

  // 0) mostra de imediato as imagens da pasta logos/ e o que ja tinha sido achado (sem esperar a TV)
  resolveIcons();

  luna("luna://com.webos.applicationManager/listLaunchPoints", {},
    function (res) { dbg.lp = "erro: " + (res.errorText || res.errorCode || "?"); oneDone(); },
    function (res) {
      var lp = res.launchPoints || [];
      dbg.lp = "ok, " + lp.length + " itens";
      lp.forEach(function (p) {
        tvAdd({ id: p.id, title: p.title, icon: p.icon, largeIcon: p.largeIcon, folderPath: "" });
      });
      oneDone();
    });

  luna("luna://com.webos.applicationManager/listApps", {},
    function (res) { dbg.la = "erro: " + (res.errorText || res.errorCode || "?"); oneDone(); },
    function (res) {
      var ap = res.apps || [];
      dbg.la = "ok, " + ap.length + " itens";
      ap.forEach(function (a) {
        tvAdd({ id: a.id, title: a.title, icon: a.icon, largeIcon: a.largeIcon, folderPath: a.folderPath || "" });
      });
      oneDone();
    });

  setTimeout(settle, 2500);                       // se a TV nao responder
}

