// ---------- conversa com a TV ----------
function getSetting(cat, key, cb) {
  luna("luna://com.webos.service.settings/getSystemSettings", { category: cat, keys: [key] },
    function () { S.fail++; cb(null); },
    function (res) {
      var v = res.settings ? res.settings[key] : null;
      if (v === undefined) v = null;
      S.ok++; cb(v);
    });
}

function refreshSettings() {
  S.ok = 0; S.fail = 0;
  luna("luna://com.webos.service.connectionmanager/getStatus", {},
    function () { S.fail++; S.wifi = null; S.wired = null; refreshRows(); },
    function (res) {
      S.ok++;
      var w = res.wifi || {}, c = res.wired || {};
      S.wifi = w.state === "connected" ? (w.ssid || "Conectado") : "Desconectado";
      S.wired = c.state === "connected" ? "Conectado" : "Sem cabo";
      refreshRows();
    });
  getSetting("picture", "pictureMode", function (v) { S.pic = v; refreshRows(); });
  getSetting("sound", "soundMode",     function (v) { S.snd = v; refreshRows(); });
  getSetting("sound", "soundOutput",   function (v) { S.out = v; refreshRows(); });
  luna("luna://com.webos.audio/getVolume", {},
    function () { S.fail++; },
    function (res) {
      var v = res.volume;
      if (v === undefined && res.volumeStatus) v = res.volumeStatus.volume;
      if (typeof v === "number") { S.ok++; S.vol = v; refreshRows(); }
    });
  setTimeout(function () { sNoRead = (S.ok === 0 && S.fail > 0); setHint(); }, 1800);
}

function failToast() { toast("A TV não deixou mudar isso por aqui. Use “Todas as configurações”."); }

function applySet(cat, key, val, field) {
  var old = S[field];
  S[field] = val; refreshRows();
  var st = {}; st[key] = val;
  luna("luna://com.webos.service.settings/setSystemSettings", { category: cat, settings: st },
    function () { S[field] = old; refreshRows(); failToast(); });
}

function openSys() {
  luna("luna://com.webos.applicationManager/launch", { id: "com.palm.app.settings" },
    function () { toast("Não consegui abrir as configurações da TV."); });
}

function adjVol(d) {
  var v = S.vol === null ? 20 : S.vol;
  v = Math.max(0, Math.min(100, v + d * 5));
  S.vol = v; refreshRows();
  luna("luna://com.webos.audio/setVolume", { volume: v }, function () { toast("Não consegui mudar o volume por aqui."); });
}

function toggleGame() {
  if (S.pic === "game") {
    var prev = recall("hz_prevpic", "standard");
    applySet("picture", "pictureMode", prev === "game" ? "standard" : prev, "pic");
  } else {
    store("hz_prevpic", S.pic || "standard");
    applySet("picture", "pictureMode", "game", "pic");
  }
}

