  var i, c = $("scats").children;
  for (i = 0; i < c.length; i++) {
    c[i].classList.toggle("focus", sFocus === "cats" && i === cIndex);
    c[i].classList.toggle("sel", i === cIndex);
  }
  var rows = curRows();
  for (i = 0; i < rows.length; i++) if (rows[i].el) rows[i].el.classList.toggle("focus", sFocus === "rows" && i === rIndex);
  setHint();
}

function rowEl(r, i) {
  var el = document.createElement("div"); el.className = "row"; el.style.setProperty("--ri", i);
