  var lb = document.createElement("div"); lb.className = "rl"; lb.textContent = r.label;
  el.appendChild(ic); el.appendChild(lb);
  if (r.val) { r.vEl = document.createElement("div"); r.vEl.className = "rv"; el.appendChild(r.vEl); }
  r.xEl = document.createElement("div");
  if (r.on) r.xEl.className = "rx sw";
  else if (r.pct) { r.xEl.className = "rx sl"; r.xEl.innerHTML = "<i></i>"; }
  else { r.xEl.className = "rx chev"; r.xEl.textContent = "›"; }
  el.appendChild(r.xEl);
  r.el = el;
  el.addEventListener("mouseenter", function () { if (introDone && screen === "settings") { sFocus = "rows"; rIndex = i; paintSettings(); } });
  el.addEventListener("click", function () { if (introDone && screen === "settings") { sFocus = "rows"; rIndex = i; paintSettings(); activateRow(r); } });
  return el;
}

