function settingsKey(k) {
  if (sFocus === "cats") {
    if (k === 38) selectCat(cIndex - 1);
    else if (k === 40) selectCat(cIndex + 1);
    else if (k === 39 || k === 13) { sFocus = "rows"; rIndex = 0; paintSettings(); }
    else if (k === 461 || k === 27) closeSettings();
    return;
  }
  var rows = curRows(), r = rows[rIndex];
  if (k === 38) { if (rIndex > 0) { rIndex--; paintSettings(); } }
  else if (k === 40) { if (rIndex < rows.length - 1) { rIndex++; paintSettings(); } }
  else if (k === 37) { if (r.adj) r.adj(-1); else { sFocus = "cats"; paintSettings(); } }
  else if (k === 39) { if (r.adj) r.adj(1); }
  else if (k === 13) activateRow(r);
  else if (k === 461 || k === 27) { sFocus = "cats"; paintSettings(); }
}

