// NOTICIAS REAIS + ATUALIZACAO PELO SITE
// Fonte 1: news.json do seu site (o GitHub monta a cada ~20 min com G1, ge, Tecnoblog...)
// Fonte 2 (reserva, nao precisa configurar nada): os mesmos jornais via rss2json.com
// A ultima lista fica guardada: aparece na hora ao abrir, mesmo sem internet.
// ============================================================
var newsInfo = { state: "loading", at: 0, from: "" };   // loading | ok | stale | offline
var autoUpd = true, updState = "";
var CATCOL = {
  "Brasil": ["#00e5ff", "#2f6bff"], "Mundo": ["#ff2fd0", "#7b2ff7"], "Esportes": ["#22d36b", "#0e8a45"],
  "Tecnologia": ["#ffa522", "#e0452f"], "Economia": ["#ffd23f", "#c77d00"], "Entretenimento": ["#ff5e7e", "#a1234d"]
};
function catColors(c) { return CATCOL[c] || ["#59c7ff", "#1e5fa8"]; }
function artBg(n) {
  var c = catColors(n.cat);
  return (n.img ? 'url("' + n.img.replace(/"/g, "%22") + '"),' : "") + "linear-gradient(135deg," + c[0] + "," + c[1] + ")";
}
function ago(ts) {
  if (!ts) return "";
  var m = Math.round((Date.now() - ts) / 60000);
  if (m < 2) return "agora";
  if (m < 60) return "há " + m + " min";
  var h = Math.round(m / 60);
  if (h < 24) return "há " + h + " h";
  var d = Math.round(h / 24);
  return "há " + d + (d === 1 ? " dia" : " dias");
}
function newsSub(n) { var a = ago(n.ts); return n.src + (a ? " · " + a : ""); }
function hhmm(ts) { var d = new Date(ts); return ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2); }
function newsMsg() {
  if (newsInfo.state === "loading") return "Carregando notícias…";
  return "Sem notícias agora. Verifique a internet.";
}
function newsStatus() {
  if (newsInfo.state === "loading" && !NEWS.length) return "carregando…";
  if (!NEWS.length) return "sem conexão";
  var t = newsInfo.at ? "atualizado " + hhmm(newsInfo.at) : "";
  return NEWS.length + " matérias" + (t ? " · " + t : "") + (newsInfo.state === "stale" ? " (antigas)" : "");
}

function getJSON(url, ms, ok, fail) {
  var x = new XMLHttpRequest(), done = false;
  function bad() { if (!done) { done = true; if (fail) fail(); } }
  try {
    x.open("GET", url, true);
    x.timeout = ms;
    x.onerror = x.ontimeout = bad;
    x.onload = function () {
      var j = null;
      try { j = JSON.parse(x.responseText); } catch (e) {}
      if (x.status === 200 && j) { if (!done) { done = true; ok(j); } } else bad();
    };
    x.send();
  } catch (e) { bad(); }
}
function plain(h) {
  return String(h || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/\s+/g, " ").replace(/^\s+|\s+$/g, "");
}
function cleanItems(list) {
  var out = [], seen = {};
  (list || []).forEach(function (n) {
    if (!n || !n.t || !n.url) return;
    var k = n.t.toLowerCase().slice(0, 60);
    if (seen[k]) return; seen[k] = 1;
    out.push({ t: String(n.t), s: String(n.s || ""), src: String(n.src || ""), cat: String(n.cat || "Brasil"),
               img: n.img && /^https?:/i.test(n.img) ? String(n.img) : "", url: String(n.url), ts: +n.ts || 0 });
  });
  return out;
}
function mixByCat(items) {                     // intercala categorias: o comeco da lista fica variado
  var by = {}, order = [], out = [], more = true, i;
  items.sort(function (a, b) { return b.ts - a.ts; });
  items.forEach(function (n) { if (!by[n.cat]) { by[n.cat] = []; order.push(n.cat); } by[n.cat].push(n); });
  for (i = 0; more; i++) {
    more = false;
    order.forEach(function (c) { if (by[c][i]) { out.push(by[c][i]); more = true; } });
  }
  return out;
}
var RSS_FEEDS = [
  { cat: "Brasil", src: "G1", url: "https://g1.globo.com/rss/g1/" },
  { cat: "Esportes", src: "ge", url: "https://ge.globo.com/rss/ge/" },
  { cat: "Tecnologia", src: "Tecnoblog", url: "https://tecnoblog.net/feed/" },
  { cat: "Mundo", src: "G1 Mundo", url: "https://g1.globo.com/rss/g1/mundo/" },
  { cat: "Economia", src: "G1 Economia", url: "https://g1.globo.com/rss/g1/economia/" }
];
function viaRss2Json(done) {
  var all = [], left = RSS_FEEDS.length;
  function fin() { if (--left === 0) done(mixByCat(cleanItems(all))); }
  RSS_FEEDS.forEach(function (f) {
    getJSON("https://api.rss2json.com/v1/api.json?rss_url=" + encodeURIComponent(f.url), 12000, function (j) {
      (j.items || []).slice(0, 8).forEach(function (it) {
        var img = it.thumbnail || (it.enclosure && it.enclosure.link) || "";
        if (!/\.(jpe?g|png|webp)/i.test(img) && !/^https?:\/\/.*(glbimg|img|image|wp-content)/i.test(img)) img = "";
        if (!img) { var m = /<img[^>]+src=["']([^"']+)/i.exec((it.content || "") + (it.description || "")); if (m) img = m[1]; }
        var ts = Date.parse(String(it.pubDate || "").replace(" ", "T") + "Z") || 0;
        all.push({ t: plain(it.title), s: plain(it.description || it.content).slice(0, 280), src: f.src, cat: f.cat, img: img, url: it.link, ts: ts });
      });
      fin();
    }, fin);
  });
}
var newsBusy = false;
function newsChanged() {
  if (bnIdx > NEWS.length - 1) bnIdx = Math.max(0, NEWS.length - 1);
  if (newsIdx > NEWS.length - 1) newsIdx = Math.max(0, NEWS.length - 1);
  buildNewsPanel(); buildCyber(); refreshFocus();
  if (typeof refreshRows === "function") refreshRows();
}
function loadNews(manual) {
  if (newsBusy) return;
  newsBusy = true;
  if (manual) toast("Atualizando notícias…");
  function ok(items, from) {
    newsBusy = false;
    NEWS = items; newsInfo = { state: "ok", at: Date.now(), from: from };
    store("hz_news_cache", JSON.stringify({ at: newsInfo.at, items: items.slice(0, 40) }));
    newsChanged();
    if (manual) toast("Notícias atualizadas: " + items.length + " matérias");
  }
  function fail() {
    newsBusy = false;
    newsInfo.state = NEWS.length ? "stale" : "offline";
    newsChanged();
    if (manual) toast("Não consegui buscar as notícias. Confira a internet da TV.");
  }
  function fallback() { viaRss2Json(function (items) { if (items.length) ok(items, "rss"); else fail(); }); }
  var site = window.HZOTA ? HZOTA.site() : "";
  if (!site) { fallback(); return; }
  getJSON(site + "news.json?t=" + Date.now(), 12000, function (j) {
    var items = cleanItems(j.items);
    if (items.length) ok(items, "site"); else fallback();
  }, fallback);
}
(function () {                                 // mostra na hora o que ficou guardado
  try {
    var c = JSON.parse(recall("hz_news_cache", "null"));
    if (c && c.items && c.items.length) { NEWS = cleanItems(c.items); newsInfo = { state: "stale", at: c.at || 0, from: "cache" }; }
  } catch (e) {}
})();

