    else if (r.state === "bad") { updState = "versão " + r.version + " deu erro e foi ignorada"; if (manual) toast(updState); }
    else { updState = "sem conexão com o site"; if (manual) toast("Não consegui falar com o site. Confira o endereço e a internet."); }
